"""Local model-provider abstraction. JSON actions are genuinely generated by Qwen."""

from __future__ import annotations

import time
from typing import Any, Protocol
from urllib.parse import urlparse

import requests


class ProviderError(RuntimeError):
    pass


class ModelProvider(Protocol):
    def generate(
        self, messages: list[dict[str, str]], schema: dict[str, Any]
    ) -> tuple[str, dict[str, Any]]: ...


class OllamaProvider:
    """Single server/model instance; each caller supplies an isolated role history.

    Uses Ollama's constrained JSON format for typed tool-action dispatch, not an
    assertion that message.tool_calls/native tool calling was used.
    """

    def __init__(
        self,
        url: str = "http://127.0.0.1:11435",
        model: str = "qwen2.5:1.5b-instruct",
        timeout: float = 45.0,
        context: int = 4096,
    ) -> None:
        parsed = urlparse(url)
        if parsed.scheme != "http" or parsed.hostname not in {"localhost", "127.0.0.1", "::1"}:
            raise ValueError("This Ollama provider accepts only local loopback HTTP endpoints")
        self.url, self.model, self.timeout, self.context = url.rstrip("/"), model, timeout, context

    def generate(self, messages: list[dict[str, str]], schema: dict[str, Any]) -> tuple[str, dict[str, Any]]:
        started = time.perf_counter()
        payload = {
            "model": self.model,
            "messages": messages,
            "format": schema,
            "stream": False,
            "keep_alive": "10m",
            "options": {
                "temperature": 0,
                "seed": 42,
                "num_predict": 192,
                "num_ctx": self.context,
                "num_gpu": 99,
            },
        }
        try:
            response = requests.post(self.url + "/api/chat", json=payload, timeout=(5, self.timeout))
            response.raise_for_status()
            data = response.json()
            content = data["message"]["content"]
            if not isinstance(content, str) or not content:
                raise ProviderError("Model returned no structured action")
            metadata = {
                key: data.get(key)
                for key in (
                    "model",
                    "done",
                    "eval_count",
                    "eval_duration",
                    "prompt_eval_count",
                    "load_duration",
                )
            }
            metadata["wall_seconds"] = time.perf_counter() - started
            return content, metadata
        except (requests.RequestException, KeyError, ValueError) as error:
            raise ProviderError(f"Ollama inference failed: {type(error).__name__}: {error}") from error

    def audit(self) -> dict[str, Any]:
        version = requests.get(self.url + "/api/version", timeout=10).json()
        details = requests.post(self.url + "/api/show", json={"model": self.model}, timeout=10).json()
        running = requests.get(self.url + "/api/ps", timeout=10).json()
        return {
            "url": self.url,
            "requested_model": self.model,
            "version": version,
            "model_details": details,
            "running_models": running,
        }
